<?php require_once __DIR__ . '/../config/config.php'; require_role('admin'); if(!is_post()) redirect('admin/impostazioni.php'); foreach($_POST as $k=>$v){$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute([$k,$v]);} set_flash('success','Impostazioni salvate'); redirect('admin/impostazioni.php');